-- Populate Mezmur category & occasion links from the lyrics classification
-- (all 2,092 classified Mezmurs, every confidence level, as requested).
-- ADD-ONLY: existing links are kept (ON CONFLICT DO NOTHING). No Mezmur row,
-- lyric, title, slug, URL, publication status or RLS policy is changed.
-- Identity: import_id first; if that row no longer exists, a unique slug match,
-- then a unique title match, among non-deleted Mezmurs. Anything ambiguous or
-- missing is skipped and listed at the end.
begin;
set local statement_timeout = '300s';

create temporary table cls_stage(
  import_id uuid, slug text, title text, title_amharic text,
  categories text[], occasions text[], confidence text
) on commit drop;


-- Resolve each classified Mezmur to a current, non-deleted record.
create temporary table cls_resolved on commit drop as
with live as (
  select import_id, slug, title, title_amharic from public.mezmur_data_import where deleted_at is null
),
by_id as (
  select s.*, l.import_id as target, 'import_id' as matched_by
  from cls_stage s join live l on l.import_id = s.import_id
),
by_slug as (
  select s.*, (array_agg(l.import_id))[1] as target, 'slug' as matched_by
  from cls_stage s join live l on lower(trim(l.slug)) = lower(trim(s.slug))
  where not exists (select 1 from by_id b where b.import_id = s.import_id)
  group by s.import_id, s.slug, s.title, s.title_amharic, s.categories, s.occasions, s.confidence
  having count(*) = 1
),
by_title as (
  select s.*, (array_agg(l.import_id))[1] as target, 'title' as matched_by
  from cls_stage s join live l
    on (nullif(trim(s.title_amharic),'') is not null and trim(l.title_amharic) = trim(s.title_amharic))
    or (nullif(trim(s.title_amharic),'') is null and lower(trim(l.title)) = lower(trim(s.title)))
  where not exists (select 1 from by_id b where b.import_id = s.import_id)
    and not exists (select 1 from by_slug b where b.import_id = s.import_id)
  group by s.import_id, s.slug, s.title, s.title_amharic, s.categories, s.occasions, s.confidence
  having count(*) = 1
)
select * from by_id union all select * from by_slug union all select * from by_title;

-- Two classified rows can land on the same live Mezmur; links are merged.
select distinct on (r.target, c.slug)
       r.target, m.slug, c.slug,
       case when c.ord = 1 then 'lyrics-classifier-primary' else 'lyrics-classifier-secondary' end,
       r.confidence
from cls_resolved r
join public.mezmur_data_import m on m.import_id = r.target
cross join lateral unnest(r.categories) with ordinality as c(slug, ord)
order by r.target, c.slug, c.ord
on conflict (mezmur_import_id, category_slug) do nothing;

select distinct on (r.target, o.slug)
       r.target, m.slug, o.slug,
       case when o.ord = 1 then 'lyrics-classifier-primary' else 'lyrics-classifier-secondary' end
from cls_resolved r
join public.mezmur_data_import m on m.import_id = r.target
cross join lateral unnest(r.occasions) with ordinality as o(slug, ord)
order by r.target, o.slug, o.ord
on conflict (mezmur_import_id, occasion_slug) do nothing;

-- Public link views: keep the same four columns and grants, but also show
-- links for published Mezmurs whose legacy mezmur_id is empty (matched by a
-- unique slug), so classified songs without that legacy id are counted too.
create or replace view public.mezmur_category_links_public
with (security_barrier=true) as
select distinct l.mezmur_import_id, m.mezmur_id, m.slug as mezmur_slug, l.category_slug
from public.mezmur_category_links_import l
join public.mezmur_data_import m on m.import_id = l.mezmur_import_id
where l.mezmur_import_id is not null
  and m.deleted_at is null
  and lower(trim(coalesce(m.status,''))) = 'published'
  and exists (
    select 1 from public.mezmur_public p
    where (m.mezmur_id is not null and p.mezmur_id = m.mezmur_id)
       or (m.mezmur_id is null
           and lower(trim(p.slug)) = lower(trim(m.slug))
           and (select count(*) from public.mezmur_public px where lower(trim(px.slug)) = lower(trim(m.slug))) = 1)
  );

create or replace view public.mezmur_occasion_links_public
with (security_barrier=true) as
select distinct l.mezmur_import_id, m.mezmur_id, m.slug as mezmur_slug, l.occasion_slug
from public.mezmur_occasion_links_import l
join public.mezmur_data_import m on m.import_id = l.mezmur_import_id
where l.mezmur_import_id is not null
  and m.deleted_at is null
  and lower(trim(coalesce(m.status,''))) = 'published'
  and exists (
    select 1 from public.mezmur_public p
    where (m.mezmur_id is not null and p.mezmur_id = m.mezmur_id)
       or (m.mezmur_id is null
           and lower(trim(p.slug)) = lower(trim(m.slug))
           and (select count(*) from public.mezmur_public px where lower(trim(px.slug)) = lower(trim(m.slug))) = 1)
  );

grant select on public.mezmur_category_links_public to anon, authenticated;
grant select on public.mezmur_occasion_links_public to anon, authenticated;

commit;

-- Summary (read-only).
select
  (select count(*) from public.mezmur_category_links_import) as category_links_total,
  (select count(*) from public.mezmur_occasion_links_import) as occasion_links_total,
  (select count(*) from public.mezmur_category_links_public) as category_links_visible,
  (select count(*) from public.mezmur_occasion_links_public) as occasion_links_visible,
  (select count(distinct mezmur_import_id) from public.mezmur_category_links_public) as mezmurs_with_visible_category;
